 public override async void _Process(double ignored){if(!ready)return;try{if(host.IsProcessing())throw new Exception("auto process enabled");long old=sim.Tick; bool beforeActive=Active(); sim.TryGetEntity(sim.PlayerId,out var beforePlayer); float input=frame<60?0:frame<132?1:frame<204?-1:0;Call("SynchronizeMovementInput");var router=Field<MoveInputRouter>("_moveInputs");if(!host.SubmitMovementIntent(router.Token("route"),new MoveIntent(input,0)))throw new Exception("route rejected");host._Process(GameSimulation.FixedDelta); bool afterActive=Active();if(!beforeActive&&afterActive)sequence++;sim.TryGetEntity(sim.PlayerId,out var afterPlayer);if(sim.Tick-old!=1)throw new Exception("not exactly one tick/render");GetWindow().ContentScaleSize=new(1280,720);GetWindow().ContentScaleMode=Window.ContentScaleModeEnum.Viewport;GetWindow().ContentScaleAspect=Window.ContentScaleAspectEnum.Keep;var state=State();authority.AppendLine(JsonSerializer.Serialize(state,J));var actor=Field<Node3D[]>("_visuals")[sim.PlayerId.Index];cameras.Append(frame).Append('|').Append(T(camera.GlobalTransform)).Append('|').Append(N(camera.Size)).Append('|').Append(T(actor.GlobalTransform)).AppendLine();var observed=Field<Node3D[]>("_visuals")[sim.PlayerId.Index];motion.AppendLine(JsonSerializer.Serialize(new{frame,sim.Tick,input,beforeActive,afterActive,observedStart=!beforeActive&&afterActive,observedSequence=sequence,clip=Field<CharacterPresentation[]>("_presentations")[sim.PlayerId.Index]?.CurrentClip,yaw=observed.Rotation.Y,position=afterPlayer.Position,velocity=new Vec2((afterPlayer.Position.X-beforePlayer.Position.X)/GameSimulation.FixedDelta,(afterPlayer.Position.Y-beforePlayer.Position.Y)/GameSimulation.FixedDelta),afterPlayer.Facing,afterPlayer.Health,sim.Phase,sim.Paused},J));poses.Append(frame).Append('|').Append(Pose(actor)).AppendLine();
 {int bits=(frame+43)&255;for(int i=0;i<8;i++)stamp[i].Color=(bits&(1<<i))!=0?Colors.White:Colors.Black;if(framecheck&&frame==65){SetProcess(false);long tick=sim.Tick;await ToSignal(RenderingServer.Singleton,RenderingServer.SignalName.FramePostDraw);if(sim.Tick!=tick)throw new Exception("framecheck advanced");using var image=GetTree().Root.GetTexture().GetImage();if(image.GetSize()!=new Vector2I(1280,720))throw new Exception("root viewport");int decoded=0;for(int i=0;i<8;i++)if(image.GetPixel(14+i*14,702).R>.5)decoded|=1<<i;if(decoded!=bits)throw new Exception("framebuffer stamp");image.SavePng(folder+"/framecheck.png");using var game=view.GetTexture().GetImage();game.SavePng(folder+"/framecheck-game.png");File.WriteAllText(folder+"/framecheck.json",JsonSerializer.Serialize(state,J));Finish();return;}}
